using System;
using System.Collections;
using System.Collections.Generic;
using System.Configuration;
using System.Data;
using System.Data.SqlClient;

namespace WebPortal.App_Code
{
 public sealed class SoftwareRequestRepository
 {
  private static SqlConnection Open(){var c=new SqlConnection(ConfigurationManager.ConnectionStrings["MainCon"].ConnectionString);c.Open();return c;}
  private static void Add(SqlCommand c,string n,object v){c.Parameters.AddWithValue(n,v??DBNull.Value);}
  private static DataSet Set(SqlCommand c){using(var a=new SqlDataAdapter(c)){var d=new DataSet();a.Fill(d);return d;}}
  private static DataTable Table(SqlCommand c){using(var a=new SqlDataAdapter(c)){var t=new DataTable();a.Fill(t);return t;}}
  private const string ActiveSoftwareEmployee=@"SELECT e.EmployeeID,e.Code+' : '+LTRIM(RTRIM(ISNULL(e.FirstName,'')+' '+ISNULL(e.lastName,''))) DisplayName,e.Code RoleCode FROM dbo.EmployeeInfo e WHERE e.Department=12 AND ISNULL(e.IsDelete,0)=0 AND NOT EXISTS(SELECT 1 FROM dbo.InitiateResignation ir WHERE ir.EmployeeID=e.EmployeeID AND CAST(ir.LastworkingDate AS date)<CAST(GETDATE() AS date))";
  public bool IsTeam(int id){using(var cn=Open())using(var c=new SqlCommand("SELECT COUNT(1) FROM ("+ActiveSoftwareEmployee+") e WHERE e.EmployeeID=@E",cn)){Add(c,"@E",id);return Convert.ToInt32(c.ExecuteScalar())>0;}}
  public string EmployeeCode(int id){using(var cn=Open())using(var c=new SqlCommand("SELECT Code FROM dbo.EmployeeInfo WHERE EmployeeID=@E AND ISNULL(IsDelete,0)=0",cn)){Add(c,"@E",id);return Convert.ToString(c.ExecuteScalar());}}
  public DataSet Bootstrap(int id)
  {using(var cn=Open())using(var c=new SqlCommand(@"SELECT RequestTypeID,RequestTypeName FROM dbo.SRM_RequestType WHERE IsActive=1 ORDER BY RequestTypeName;
SELECT ApplicationID,ApplicationName,IsBusinessCritical FROM dbo.SRM_Application WHERE IsActive=1 ORDER BY ApplicationName;
SELECT ModuleID,ApplicationID,ModuleName,IsBusinessCritical FROM dbo.SRM_Module WHERE IsActive=1 ORDER BY ModuleName;
SELECT PriorityCode,PriorityName FROM dbo.SRM_Priority WHERE IsActive=1 ORDER BY SortOrder;
SELECT StatusCode,StatusName FROM dbo.SRM_Status WHERE IsActive=1 ORDER BY SortOrder;
"+ActiveSoftwareEmployee+@" ORDER BY DisplayName;
SELECT CAST(CASE WHEN EXISTS(SELECT 1 FROM ("+ActiveSoftwareEmployee+@") e WHERE e.EmployeeID=@E) THEN 1 ELSE 0 END AS bit) IsSoftwareUser;",cn)){Add(c,"@E",id);return Set(c);}}
  public long Create(Hashtable v)
  {using(var cn=Open())using(var tr=cn.BeginTransaction())try{long id;using(var c=new SqlCommand(@"INSERT dbo.SRM_Request(RequestedBy,RequestOwnerCode,RequestedByName,Department,RequestTypeID,ApplicationID,ModuleID,Title,Description,BusinessJustification,RequestedPriority,RequiredByDate,UpdatedBy) VALUES(@By,@OwnerCodes,@ByName,@Department,@Type,@Application,NULLIF(@Module,0),@Title,@Description,@Justification,@Priority,@RequiredBy,@By);SELECT CAST(SCOPE_IDENTITY() AS bigint);",cn,tr)){foreach(DictionaryEntry x in v)Add(c,"@"+x.Key,x.Value);id=Convert.ToInt64(c.ExecuteScalar());}string no="SWR-"+DateTime.Now.Year+"-"+id.ToString("D6");using(var c=new SqlCommand("UPDATE dbo.SRM_Request SET RequestNo=@No WHERE RequestID=@ID;INSERT dbo.SRM_History(RequestID,FieldName,NewValue,Remarks,ChangedBy) VALUES(@ID,'Status','New','Request submitted',@By);",cn,tr)){Add(c,"@No",no);Add(c,"@ID",id);Add(c,"@By",v["By"]);c.ExecuteNonQuery();}tr.Commit();return id;}catch{tr.Rollback();throw;}}
  public DataSet Dashboard(int employeeId,bool canViewAll)
  {using(var cn=Open())using(var c=new SqlCommand(@"SELECT SUM(CASE WHEN StatusCode='New' THEN 1 ELSE 0 END) NewCount,SUM(CASE WHEN StatusCode='In Progress' THEN 1 ELSE 0 END) InProgressCount,SUM(CASE WHEN StatusCode='On Hold' THEN 1 ELSE 0 END) OnHoldCount,SUM(CASE WHEN StatusCode='Testing' THEN 1 ELSE 0 END) TestingCount,SUM(CASE WHEN StatusCode='Completed' THEN 1 ELSE 0 END) CompletedCount FROM dbo.SRM_Request WHERE IsDeleted=0 AND (@All=1 OR RequestedBy=@E);",cn)){Add(c,"@E",employeeId);Add(c,"@All",canViewAll);return Set(c);}}
  public DataTable List(int employeeId,bool canViewAll,string scope,string search,string requester,string department,int applicationId,int moduleId,int developerId,string priority,string status)
  {using(var cn=Open())using(var c=new SqlCommand(@"SELECT r.RequestID,r.RequestNo,r.RequestDate,r.Title RequestTitle,a.ApplicationName,m.ModuleName,r.RequestedByName,r.Department,COALESCE(r.FinalPriority,r.RequestedPriority) Priority,r.AssignedDeveloperName,r.StatusCode,r.ExpectedCompletionDate,r.UpdatedOn,(CASE WHEN a.IsBusinessCritical=1 OR ISNULL(m.IsBusinessCritical,0)=1 THEN 1 ELSE 0 END) IsBusinessCritical FROM dbo.SRM_Request r JOIN dbo.SRM_Application a ON a.ApplicationID=r.ApplicationID LEFT JOIN dbo.SRM_Module m ON m.ModuleID=r.ModuleID WHERE r.IsDeleted=0 AND ((@Scope='Mine' AND r.RequestedBy=@E) OR (@Scope<>'Mine' AND @All=1)) AND (@Search='' OR r.RequestNo LIKE '%'+@Search+'%' OR r.Title LIKE '%'+@Search+'%') AND (@Requester='' OR r.RequestedByName LIKE '%'+@Requester+'%') AND (@Department='' OR r.Department=@Department) AND (@Application=0 OR r.ApplicationID=@Application) AND (@Module=0 OR r.ModuleID=@Module) AND (@Developer=0 OR r.AssignedDeveloperID=@Developer) AND (@Priority='' OR COALESCE(r.FinalPriority,r.RequestedPriority)=@Priority) AND (@Status='' OR r.StatusCode=@Status) ORDER BY CASE WHEN a.IsBusinessCritical=1 OR ISNULL(m.IsBusinessCritical,0)=1 THEN 0 ELSE 1 END,CASE COALESCE(r.FinalPriority,r.RequestedPriority) WHEN 'Critical' THEN 1 WHEN 'High' THEN 2 WHEN 'Medium' THEN 3 ELSE 4 END,ISNULL(r.ExpectedCompletionDate,'99991231'),r.RequestDate;",cn)){Add(c,"@E",employeeId);Add(c,"@All",canViewAll);Add(c,"@Scope",scope??"Mine");Add(c,"@Search",search??"");Add(c,"@Requester",requester??"");Add(c,"@Department",department??"");Add(c,"@Application",applicationId);Add(c,"@Module",moduleId);Add(c,"@Developer",developerId);Add(c,"@Priority",priority??"");Add(c,"@Status",status??"");return Table(c);}}
  public DataTable TaskOwners(int employeeId,bool canViewAll){using(var cn=Open())using(var c=new SqlCommand(@"SELECT r.RequestID,STUFF((SELECT ' / '+e.Code+' : '+LTRIM(RTRIM(ISNULL(e.FirstName,'')+' '+ISNULL(e.lastName,''))) FROM dbo.EmployeeInfo e WHERE '/'+ISNULL(r.RequestOwnerCode,'')+'/' LIKE '%/'+e.Code+'/%' ORDER BY e.FirstName,e.lastName FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),1,3,'') TaskOwnerName FROM dbo.SRM_Request r WHERE r.IsDeleted=0 AND (@All=1 OR r.RequestedBy=@E)",cn)){Add(c,"@E",employeeId);Add(c,"@All",canViewAll);return Table(c);}}
  public DataSet Detail(long id,int employeeId,bool canViewAll)
  {using(var cn=Open())using(var c=new SqlCommand(@"IF NOT EXISTS(SELECT 1 FROM dbo.SRM_Request WHERE RequestID=@ID AND IsDeleted=0 AND (@All=1 OR RequestedBy=@E)) THROW 50001,'Access denied.',1;
SELECT r.*,t.RequestTypeName,a.ApplicationName,m.ModuleName,approver.Code+' : '+LTRIM(RTRIM(ISNULL(approver.FirstName,'')+' '+ISNULL(approver.lastName,''))) PriorityApprovedByName,(CASE WHEN a.IsBusinessCritical=1 OR ISNULL(m.IsBusinessCritical,0)=1 THEN 1 ELSE 0 END) IsBusinessCritical FROM dbo.SRM_Request r JOIN dbo.SRM_RequestType t ON t.RequestTypeID=r.RequestTypeID JOIN dbo.SRM_Application a ON a.ApplicationID=r.ApplicationID LEFT JOIN dbo.SRM_Module m ON m.ModuleID=r.ModuleID LEFT JOIN dbo.EmployeeInfo approver ON approver.EmployeeID=r.PriorityApprovedBy WHERE r.RequestID=@ID;
;WITH Updates AS(SELECT h.RequestID,h.ChangedOn,MAX(CASE WHEN h.FieldName='Assignment' THEN h.NewValue END) DeveloperID,MAX(CASE WHEN h.FieldName IN('Status','Import') THEN h.NewValue END) StatusCode,MAX(CASE WHEN h.FieldName='Completion' THEN h.NewValue END) ExpectedCompletionDate,MAX(CASE WHEN h.FieldName='Update' THEN h.NewValue END) DeveloperRemark,MAX(CASE WHEN h.FieldName='Hold Reason' THEN h.NewValue END) HoldReason,MAX(h.Remarks) Remarks FROM dbo.SRM_History h WHERE h.RequestID=@ID GROUP BY h.RequestID,h.ChangedOn)
SELECT u.ChangedOn,CASE WHEN COALESCE(u.DeveloperID,ad.DeveloperID) IS NULL THEN NULL ELSE e.Code+' : '+LTRIM(RTRIM(ISNULL(e.FirstName,'')+' '+ISNULL(e.lastName,''))) END AssignedDeveloper,COALESCE(u.StatusCode,st.StatusCode) StatusCode,COALESCE(u.ExpectedCompletionDate,eta.ExpectedCompletionDate) ExpectedCompletionDate,COALESCE(u.DeveloperRemark,u.Remarks) DeveloperRemark,CASE WHEN COALESCE(u.StatusCode,st.StatusCode)='On Hold' OR NULLIF(u.HoldReason,'') IS NOT NULL THEN u.HoldReason END HoldReason FROM Updates u OUTER APPLY(SELECT TOP 1 h.NewValue DeveloperID FROM dbo.SRM_History h WHERE h.RequestID=u.RequestID AND h.FieldName='Assignment' AND h.ChangedOn<=u.ChangedOn ORDER BY h.ChangedOn DESC,h.HistoryID DESC)ad OUTER APPLY(SELECT TOP 1 h.NewValue StatusCode FROM dbo.SRM_History h WHERE h.RequestID=u.RequestID AND h.FieldName IN('Status','Import') AND h.ChangedOn<=u.ChangedOn ORDER BY h.ChangedOn DESC,h.HistoryID DESC)st OUTER APPLY(SELECT TOP 1 h.NewValue ExpectedCompletionDate FROM dbo.SRM_History h WHERE h.RequestID=u.RequestID AND h.FieldName='Completion' AND h.ChangedOn<=u.ChangedOn ORDER BY h.ChangedOn DESC,h.HistoryID DESC)eta LEFT JOIN dbo.EmployeeInfo e ON e.EmployeeID=CONVERT(int,COALESCE(u.DeveloperID,ad.DeveloperID)) ORDER BY u.ChangedOn DESC;
SELECT AttachmentID,OriginalFileName,FileSize,UploadedOn FROM dbo.SRM_Attachment WHERE RequestID=@ID AND IsActive=1 ORDER BY UploadedOn DESC;",cn)){Add(c,"@ID",id);Add(c,"@E",employeeId);Add(c,"@All",canViewAll);return Set(c);}}
  public bool Update(long id,int by,int developerId,string developerName,string finalPriority,string status,DateTime? start,DateTime? completion,string update,string holdReason)
  {using(var cn=Open())using(var tr=cn.BeginTransaction())try{DataRow old;using(var c=new SqlCommand("SELECT * FROM dbo.SRM_Request WHERE RequestID=@ID",cn,tr)){Add(c,"@ID",id);var t=Table(c);if(t.Rows.Count==0)throw new InvalidOperationException("Request not found.");old=t.Rows[0];}bool notify=Convert.ToString(old["StatusCode"])!=status||Convert.ToString(old["LatestUpdate"])!=(update??"");if(status=="On Hold"&&String.IsNullOrWhiteSpace(holdReason))throw new ArgumentException("Hold reason is required.");Action<SqlCommand,string,object,object> history=(cmd,field,a,b)=>{if(Convert.ToString(a)==Convert.ToString(b))return;string token=field.Replace(" ","");cmd.CommandText+="INSERT dbo.SRM_History(RequestID,FieldName,OldValue,NewValue,Remarks,ChangedBy) VALUES(@ID"+token+",@F"+token+",@O"+token+",@N"+token+",@Remarks"+token+",@By"+token+");";Add(cmd,"@ID"+token,id);Add(cmd,"@F"+token,field);Add(cmd,"@O"+token,a);Add(cmd,"@N"+token,b);Add(cmd,"@Remarks"+token,update);Add(cmd,"@By"+token,by);};using(var c=new SqlCommand("",cn,tr)){history(c,"Status",old["StatusCode"],status);history(c,"Assignment",old["AssignedDeveloperID"],developerId);history(c,"Start",old["ExpectedStartDate"],start);history(c,"Completion",old["ExpectedCompletionDate"],completion);history(c,"Hold Reason",old["HoldReason"],status=="On Hold"?holdReason:null);if(!String.IsNullOrWhiteSpace(update))history(c,"Update",old["LatestUpdate"],update);if(c.CommandText.Length>0)c.ExecuteNonQuery();}using(var c=new SqlCommand(@"UPDATE dbo.SRM_Request SET AssignedDeveloperID=NULLIF(@Dev,0),AssignedDeveloperName=@DevName,StatusCode=@Status,ExpectedStartDate=@Start,ExpectedCompletionDate=@Completion,ActualCompletionDate=CASE WHEN @Status='Completed' THEN ISNULL(ActualCompletionDate,CAST(GETDATE() AS date)) ELSE NULL END,LatestUpdate=@Update,HoldReason=CASE WHEN @Status='On Hold' THEN @Hold ELSE NULL END,UpdatedBy=@By,UpdatedOn=SYSDATETIME() WHERE RequestID=@ID",cn,tr)){Add(c,"@Dev",developerId);Add(c,"@DevName",developerName);Add(c,"@Status",status);Add(c,"@Start",start);Add(c,"@Completion",completion);Add(c,"@Update",update);Add(c,"@Hold",holdReason);Add(c,"@By",by);Add(c,"@ID",id);c.ExecuteNonQuery();}tr.Commit();return notify;}catch{tr.Rollback();throw;}}
  public DataTable Notification(long id){using(var cn=Open())using(var c=new SqlCommand(@"SELECT r.RequestNo,r.Title,ISNULL(r.RequestOwnerCode,'')+CASE WHEN updater.Code IS NULL THEN '' ELSE '/'+updater.Code END RequestOwnerCode,r.RequestedByName,r.StatusCode,r.LatestUpdate,r.ExpectedCompletionDate,r.AssignedDeveloperName,requester.OfficialEmailID RequesterEmail,developer.OfficialEmailID DeveloperEmail FROM dbo.SRM_Request r LEFT JOIN dbo.EmployeeInfo requester ON requester.EmployeeID=r.RequestedBy LEFT JOIN dbo.EmployeeInfo developer ON developer.EmployeeID=r.AssignedDeveloperID LEFT JOIN dbo.EmployeeInfo updater ON updater.EmployeeID=r.UpdatedBy WHERE r.RequestID=@ID",cn)){Add(c,"@ID",id);return Table(c);}}
  public DataTable Emails(string[] codes){using(var cn=Open())using(var c=new SqlCommand()){c.Connection=cn;var names=new List<string>();for(int i=0;i<codes.Length;i++){string n="@C"+i;names.Add(n);Add(c,n,codes[i]);}c.CommandText=names.Count==0?"SELECT OfficialEmailID FROM dbo.EmployeeInfo WHERE 1=0":"SELECT OfficialEmailID FROM dbo.EmployeeInfo WHERE Code IN ("+String.Join(",",names)+") AND NULLIF(OfficialEmailID,'') IS NOT NULL";return Table(c);}}
  public DataTable DeveloperReport(int developerId,string scope){using(var cn=Open())using(var c=new SqlCommand(@"SELECT r.AssignedDeveloperName Developer,r.RequestNo,r.Title,a.ApplicationName,m.ModuleName,r.StatusCode,r.ExpectedCompletionDate,r.ActualCompletionDate,CASE WHEN r.StatusCode='Completed' THEN CASE WHEN r.ExpectedCompletionDate IS NULL THEN 'Completed - No Target' WHEN r.ActualCompletionDate<=r.ExpectedCompletionDate THEN 'Completed In Time' ELSE 'Completed Delayed' END WHEN r.StatusCode='On Hold' THEN 'On Hold' WHEN r.ExpectedCompletionDate IS NULL THEN 'No Timeline' WHEN r.ExpectedCompletionDate<CAST(GETDATE() AS date) THEN 'Delayed' ELSE 'In Time' END DeliveryStatus,r.LatestUpdate FROM dbo.SRM_Request r JOIN dbo.SRM_Application a ON a.ApplicationID=r.ApplicationID LEFT JOIN dbo.SRM_Module m ON m.ModuleID=r.ModuleID WHERE r.IsDeleted=0 AND r.AssignedDeveloperID IS NOT NULL AND (@Developer=0 OR r.AssignedDeveloperID=@Developer) AND ((@Scope='Current' AND r.StatusCode NOT IN('Completed','Rejected','Cancelled')) OR (@Scope='Completed' AND r.StatusCode='Completed') OR @Scope='All') ORDER BY r.AssignedDeveloperName,CASE WHEN r.StatusCode='Completed' THEN 1 ELSE 0 END,ISNULL(r.ExpectedCompletionDate,'99991231')",cn)){Add(c,"@Developer",developerId);Add(c,"@Scope",scope??"Current");return Table(c);}}
  public DataTable ActivityOwners(){using(var cn=Open())using(var c=new SqlCommand(@"SELECT EmployeeID,Code,Code+' : '+LTRIM(RTRIM(ISNULL(FirstName,'')+' '+ISNULL(lastName,''))) DisplayName FROM dbo.EmployeeInfo WHERE ISNULL(IsDelete,0)=0 ORDER BY FirstName,lastName",cn))return Table(c);}
  public long SaveActivity(long activityId,int developerId,string type,string description,int ownerId,string ownerName,DateTime activityDate,TimeSpan start,TimeSpan end,string remarks)
  {if(end<=start)throw new ArgumentException("End time must be later than start time.");using(var cn=Open())using(var tr=cn.BeginTransaction(IsolationLevel.Serializable))try{using(var c=new SqlCommand(@"IF EXISTS(SELECT 1 FROM dbo.SRM_DeveloperActivity WITH(UPDLOCK,HOLDLOCK) WHERE DeveloperID=@Developer AND ActivityDate=@Date AND IsDeleted=0 AND ActivityID<>@ID AND StartTime<@End AND EndTime>@Start) THROW 50002,'This time overlaps an existing activity.',1;",cn,tr)){Add(c,"@Developer",developerId);Add(c,"@Date",activityDate.Date);Add(c,"@ID",activityId);Add(c,"@Start",start);Add(c,"@End",end);c.ExecuteNonQuery();}long id=activityId;string ownerSql="(SELECT Code+' : '+LTRIM(RTRIM(ISNULL(FirstName,'')+' '+ISNULL(lastName,''))) FROM dbo.EmployeeInfo WHERE EmployeeID=@Owner AND ISNULL(IsDelete,0)=0)";using(var c=new SqlCommand(activityId==0?@"INSERT dbo.SRM_DeveloperActivity(DeveloperID,ActivityType,Description,OwnerEmployeeID,OwnerName,ActivityDate,StartTime,EndTime,Remarks,CreatedBy) VALUES(@Developer,@Type,@Description,@Owner,"+ownerSql+@",@Date,@Start,@End,@Remarks,@Developer);SELECT CAST(SCOPE_IDENTITY() AS bigint);":@"UPDATE dbo.SRM_DeveloperActivity SET ActivityType=@Type,Description=@Description,OwnerEmployeeID=@Owner,OwnerName="+ownerSql+@",ActivityDate=@Date,StartTime=@Start,EndTime=@End,Remarks=@Remarks,ModifiedDate=SYSDATETIME(),ModifiedBy=@Developer WHERE ActivityID=@ID AND DeveloperID=@Developer AND IsDeleted=0;IF @@ROWCOUNT=0 THROW 50003,'Activity not found or access denied.',1;SELECT @ID;",cn,tr)){Add(c,"@ID",activityId);Add(c,"@Developer",developerId);Add(c,"@Type",type);Add(c,"@Description",description);Add(c,"@Owner",ownerId);Add(c,"@Date",activityDate.Date);Add(c,"@Start",start);Add(c,"@End",end);Add(c,"@Remarks",remarks);id=Convert.ToInt64(c.ExecuteScalar());}tr.Commit();return id;}catch{tr.Rollback();throw;}}
  public DataTable Activities(int employeeId,bool canViewAll,int developerId,DateTime from,DateTime to){using(var cn=Open())using(var c=new SqlCommand(@"SELECT a.ActivityID,a.DeveloperID,e.Code+' : '+LTRIM(RTRIM(ISNULL(e.FirstName,'')+' '+ISNULL(e.lastName,''))) Developer,a.ActivityType,a.Description,a.OwnerEmployeeID,a.OwnerName,a.ActivityDate,a.StartTime,a.EndTime,a.TotalMinutes,a.Remarks,a.CreatedDate,a.ModifiedDate,CAST(CASE WHEN a.DeveloperID=@Employee THEN 1 ELSE 0 END AS bit) CanEdit FROM dbo.SRM_DeveloperActivity a JOIN dbo.EmployeeInfo e ON e.EmployeeID=a.DeveloperID WHERE a.IsDeleted=0 AND (@All=1 OR a.DeveloperID=@Employee) AND (@Developer=0 OR a.DeveloperID=@Developer) AND a.ActivityDate BETWEEN @From AND @To ORDER BY a.ActivityDate DESC,a.StartTime DESC",cn)){Add(c,"@Employee",employeeId);Add(c,"@All",canViewAll);Add(c,"@Developer",developerId);Add(c,"@From",from.Date);Add(c,"@To",to.Date);return Table(c);}}
  public DataTable ActivityNotification(long id,int developerId){using(var cn=Open())using(var c=new SqlCommand(@"SELECT a.ActivityID,a.ActivityType,a.Description,a.OwnerName,a.ActivityDate,a.StartTime,a.EndTime,a.TotalMinutes,a.Remarks,o.OfficialEmailID OwnerEmail,e.Code+' : '+LTRIM(RTRIM(ISNULL(e.FirstName,'')+' '+ISNULL(e.lastName,''))) Developer FROM dbo.SRM_DeveloperActivity a JOIN dbo.EmployeeInfo e ON e.EmployeeID=a.DeveloperID JOIN dbo.EmployeeInfo o ON o.EmployeeID=a.OwnerEmployeeID WHERE a.ActivityID=@ID AND a.DeveloperID=@Developer",cn)){Add(c,"@ID",id);Add(c,"@Developer",developerId);return Table(c);}}
  public DataSet UtilizationReport(int developerId,DateTime from,DateTime to)
  {using(var cn=Open())using(var c=new SqlCommand(@"SELECT d.EmployeeID,d.DisplayName Developer,CAST(ISNULL(SUM(a.TotalMinutes),0)/60.0 AS decimal(10,2)) OtherActivityHours FROM("+ActiveSoftwareEmployee+@")d LEFT JOIN dbo.SRM_DeveloperActivity a ON a.DeveloperID=d.EmployeeID AND a.IsDeleted=0 AND a.ActivityDate BETWEEN @From AND @To WHERE (@Developer=0 OR d.EmployeeID=@Developer) GROUP BY d.EmployeeID,d.DisplayName ORDER BY d.DisplayName;
SELECT a.ActivityDate,e.Code+' : '+LTRIM(RTRIM(ISNULL(e.FirstName,'')+' '+ISNULL(e.lastName,''))) Developer,a.ActivityType,a.OwnerName Owner,a.Description,CAST(a.TotalMinutes/60 AS varchar(10))+':'+RIGHT('0'+CAST(a.TotalMinutes%60 AS varchar(2)),2) Duration,CAST((SELECT SUM(x.TotalMinutes) FROM dbo.SRM_DeveloperActivity x WHERE x.DeveloperID=a.DeveloperID AND x.ActivityDate=a.ActivityDate AND x.IsDeleted=0)/60.0 AS decimal(10,2)) TotalDailyHours FROM dbo.SRM_DeveloperActivity a JOIN dbo.EmployeeInfo e ON e.EmployeeID=a.DeveloperID WHERE a.IsDeleted=0 AND a.ActivityDate BETWEEN @From AND @To AND (@Developer=0 OR a.DeveloperID=@Developer) ORDER BY a.ActivityDate DESC,Developer,a.StartTime;
SELECT d.EmployeeID,d.DisplayName Developer,CASE WHEN ISNULL(q.TaskCount,0)=0 THEN 'Available' WHEN q.AllocatedThrough<CAST(GETDATE() AS date) THEN 'Overdue' ELSE 'Busy' END Availability,q.AllocatedThrough,ISNULL(q.TaskCount,0) TaskCount,t.RequestNo,t.Title CurrentTask,t.StatusCode,t.Priority FROM("+ActiveSoftwareEmployee+@")d OUTER APPLY(SELECT COUNT(*) TaskCount,MAX(r.ExpectedCompletionDate) AllocatedThrough FROM dbo.SRM_Request r WHERE r.AssignedDeveloperID=d.EmployeeID AND r.IsDeleted=0 AND r.StatusCode NOT IN('Completed','Rejected','Cancelled'))q OUTER APPLY(SELECT TOP 1 r.RequestNo,r.Title,r.StatusCode,COALESCE(r.FinalPriority,r.RequestedPriority) Priority FROM dbo.SRM_Request r WHERE r.AssignedDeveloperID=d.EmployeeID AND r.IsDeleted=0 AND r.StatusCode NOT IN('Completed','Rejected','Cancelled') ORDER BY CASE COALESCE(r.FinalPriority,r.RequestedPriority) WHEN 'Critical' THEN 1 WHEN 'High' THEN 2 WHEN 'Medium' THEN 3 ELSE 4 END,ISNULL(r.ExpectedCompletionDate,'99991231'))t WHERE (@Developer=0 OR d.EmployeeID=@Developer) ORDER BY d.DisplayName;",cn)){Add(c,"@Developer",developerId);Add(c,"@From",from.Date);Add(c,"@To",to.Date);return Set(c);}}
  public DataTable PreviewPriorityImpact(long requestId,string newPriority){using(var cn=Open())using(var c=new SqlCommand(@"DECLARE @Dev int,@ETA date,@NewRank int,@OldRank int;SELECT @Dev=AssignedDeveloperID,@ETA=ExpectedCompletionDate,@OldRank=CASE COALESCE(FinalPriority,RequestedPriority) WHEN 'Critical' THEN 1 WHEN 'High' THEN 2 WHEN 'Medium' THEN 3 ELSE 4 END FROM dbo.SRM_Request WHERE RequestID=@ID;SET @NewRank=CASE @Priority WHEN 'Critical' THEN 1 WHEN 'High' THEN 2 WHEN 'Medium' THEN 3 ELSE 4 END;SELECT r.RequestID,r.RequestNo,r.Title,r.RequestedByName,r.ExpectedCompletionDate PreviousETA,DATEADD(day,1,r.ExpectedCompletionDate) RevisedETA FROM dbo.SRM_Request r WHERE @NewRank<@OldRank AND r.IsDeleted=0 AND r.RequestID<>@ID AND r.AssignedDeveloperID=@Dev AND r.StatusCode NOT IN('Completed','Rejected','Cancelled') AND r.ExpectedCompletionDate IS NOT NULL AND r.ExpectedCompletionDate>=ISNULL(@ETA,CAST(GETDATE() AS date)) AND CASE COALESCE(r.FinalPriority,r.RequestedPriority) WHEN 'Critical' THEN 1 WHEN 'High' THEN 2 WHEN 'Medium' THEN 3 ELSE 4 END>=@NewRank ORDER BY r.ExpectedCompletionDate",cn)){Add(c,"@ID",requestId);Add(c,"@Priority",newPriority);return Table(c);}}
  public long RequestPriorityChange(long requestId,int by,string newPriority,string reason,DateTime? revisedEta){using(var cn=Open())using(var c=new SqlCommand(@"DECLARE @Old varchar(20),@ETA date;SELECT @Old=COALESCE(FinalPriority,RequestedPriority),@ETA=ExpectedCompletionDate FROM dbo.SRM_Request WHERE RequestID=@ID AND IsDeleted=0;IF @Old IS NULL THROW 50004,'Task not found.',1;INSERT dbo.SRM_PriorityChange(RequestID,OldPriority,NewPriority,RequestedBy,ChangeReason,PreviousETA,RevisedETA) VALUES(@ID,@Old,@New,@By,@Reason,@ETA,@Revised);SELECT CAST(SCOPE_IDENTITY() AS bigint);",cn)){Add(c,"@ID",requestId);Add(c,"@New",newPriority);Add(c,"@By",by);Add(c,"@Reason",reason);Add(c,"@Revised",revisedEta);return Convert.ToInt64(c.ExecuteScalar());}}
  public long ApprovePriorityChange(long requestId,int by,string newPriority,string reason,DateTime? revisedEta,bool managementOverride)
  {using(var cn=Open())using(var tr=cn.BeginTransaction(IsolationLevel.Serializable))try{long changeId;string old;DateTime? previous=null;using(var c=new SqlCommand("SELECT COALESCE(FinalPriority,RequestedPriority),ExpectedCompletionDate FROM dbo.SRM_Request WITH(UPDLOCK) WHERE RequestID=@ID AND IsDeleted=0",cn,tr)){Add(c,"@ID",requestId);using(var rd=c.ExecuteReader()){if(!rd.Read())throw new InvalidOperationException("Task not found.");old=rd.GetString(0);if(!rd.IsDBNull(1))previous=rd.GetDateTime(1);}}using(var c=new SqlCommand(@"INSERT dbo.SRM_PriorityChange(RequestID,OldPriority,NewPriority,RequestedBy,ChangeReason,PreviousETA,RevisedETA,ChangeStatus,ApprovedBy,ApprovedOn,ManagementOverride) VALUES(@ID,@Old,@New,@By,@Reason,@Previous,@Revised,'Approved',@By,SYSDATETIME(),@Override);SELECT CAST(SCOPE_IDENTITY() AS bigint);",cn,tr)){Add(c,"@ID",requestId);Add(c,"@Old",old);Add(c,"@New",newPriority);Add(c,"@By",by);Add(c,"@Reason",reason);Add(c,"@Previous",previous);Add(c,"@Revised",revisedEta);Add(c,"@Override",managementOverride);changeId=Convert.ToInt64(c.ExecuteScalar());}using(var c=new SqlCommand(@"DECLARE @Dev int,@ETA date,@NewRank int;SELECT @Dev=AssignedDeveloperID,@ETA=ExpectedCompletionDate FROM dbo.SRM_Request WHERE RequestID=@ID;SET @NewRank=CASE @New WHEN 'Critical' THEN 1 WHEN 'High' THEN 2 WHEN 'Medium' THEN 3 ELSE 4 END;INSERT dbo.SRM_PriorityImpact(PriorityChangeID,CausedByRequestID,ImpactedRequestID,PreviousETA,RevisedETA,DelayDays) SELECT @Change,@ID,r.RequestID,r.ExpectedCompletionDate,DATEADD(day,1,r.ExpectedCompletionDate),1 FROM dbo.SRM_Request r WHERE r.IsDeleted=0 AND r.RequestID<>@ID AND r.AssignedDeveloperID=@Dev AND r.StatusCode NOT IN('Completed','Rejected','Cancelled') AND r.ExpectedCompletionDate IS NOT NULL AND r.ExpectedCompletionDate>=ISNULL(@ETA,CAST(GETDATE() AS date)) AND CASE COALESCE(r.FinalPriority,r.RequestedPriority) WHEN 'Critical' THEN 1 WHEN 'High' THEN 2 WHEN 'Medium' THEN 3 ELSE 4 END>=@NewRank;UPDATE r SET ExpectedCompletionDate=i.RevisedETA,RevisedETA=i.RevisedETA,UpdatedOn=SYSDATETIME() FROM dbo.SRM_Request r JOIN dbo.SRM_PriorityImpact i ON i.ImpactedRequestID=r.RequestID WHERE i.PriorityChangeID=@Change;INSERT dbo.SRM_History(RequestID,FieldName,OldValue,NewValue,Remarks,ChangedBy) SELECT ImpactedRequestID,'Priority ETA Impact',CONVERT(varchar(10),PreviousETA,120),CONVERT(varchar(10),RevisedETA,120),'Delayed by '+CAST(DelayDays AS varchar(10))+' day due to reprioritization of request '+CAST(@ID AS varchar(20)),@By FROM dbo.SRM_PriorityImpact WHERE PriorityChangeID=@Change;UPDATE dbo.SRM_Request SET FinalPriority=@New,PriorityApprovedBy=@By,PriorityApprovedOn=SYSDATETIME(),PriorityChangeReason=@Reason,RevisedETA=@Revised,ManagementOverride=@Override,ExpectedCompletionDate=COALESCE(@Revised,ExpectedCompletionDate),UpdatedBy=@By,UpdatedOn=SYSDATETIME() WHERE RequestID=@ID;INSERT dbo.SRM_History(RequestID,FieldName,OldValue,NewValue,Remarks,ChangedBy) VALUES(@ID,'Approved Priority',@Old,@New,@Reason,@By);",cn,tr)){Add(c,"@ID",requestId);Add(c,"@Change",changeId);Add(c,"@New",newPriority);Add(c,"@By",by);Add(c,"@Reason",reason);Add(c,"@Revised",revisedEta);Add(c,"@Override",managementOverride);c.ExecuteNonQuery();}tr.Commit();return changeId;}catch{tr.Rollback();throw;}}
  public DataSet PriorityHistory(long requestId){using(var cn=Open())using(var c=new SqlCommand(@"SELECT p.PriorityChangeID,p.RequestedOn ChangeDate,p.OldPriority,p.NewPriority,e.Code+' : '+LTRIM(RTRIM(ISNULL(e.FirstName,'')+' '+ISNULL(e.lastName,''))) ChangedBy,p.ChangeReason,p.PreviousETA,p.RevisedETA,p.ChangeStatus,p.ManagementOverride,p.ApprovedOn FROM dbo.SRM_PriorityChange p LEFT JOIN dbo.EmployeeInfo e ON e.EmployeeID=COALESCE(p.ApprovedBy,p.RequestedBy) WHERE p.RequestID=@ID ORDER BY p.RequestedOn DESC;SELECT i.CreatedOn,c.RequestNo CausedByTask,r.RequestNo ImpactedTask,r.Title,r.AssignedDeveloperName,i.PreviousETA,i.RevisedETA,i.DelayDays FROM dbo.SRM_PriorityImpact i JOIN dbo.SRM_Request c ON c.RequestID=i.CausedByRequestID JOIN dbo.SRM_Request r ON r.RequestID=i.ImpactedRequestID WHERE i.CausedByRequestID=@ID OR i.ImpactedRequestID=@ID ORDER BY i.CreatedOn DESC;",cn)){Add(c,"@ID",requestId);return Set(c);}}
  public DataSet PriorityImpactReport(){using(var cn=Open())using(var c=new SqlCommand(@"SELECT c.RequestNo CausedByTask,r.RequestNo ImpactedTask,r.Title,r.AssignedDeveloperName Developer,i.PreviousETA,i.RevisedETA,i.DelayDays,p.OldPriority,p.NewPriority,p.ManagementOverride,p.ChangeReason,p.ApprovedOn FROM dbo.SRM_PriorityImpact i JOIN dbo.SRM_PriorityChange p ON p.PriorityChangeID=i.PriorityChangeID JOIN dbo.SRM_Request c ON c.RequestID=i.CausedByRequestID JOIN dbo.SRM_Request r ON r.RequestID=i.ImpactedRequestID ORDER BY i.CreatedOn DESC;SELECT COUNT(*) PriorityChanges,SUM(CASE WHEN ManagementOverride=1 THEN 1 ELSE 0 END) ManagementOverrides FROM dbo.SRM_PriorityChange WHERE ChangeStatus='Approved';SELECT ISNULL(SUM(DelayDays),0) DelayDays,COUNT(DISTINCT ImpactedRequestID) ImpactedTasks FROM dbo.SRM_PriorityImpact;",cn))return Set(c);}
  public DataSet PriorityNotification(long changeId){using(var cn=Open())using(var c=new SqlCommand(@"SELECT p.*,r.RequestNo,r.Title,r.RequestedByName,r.AssignedDeveloperName,e.Code+' : '+LTRIM(RTRIM(ISNULL(e.FirstName,'')+' '+ISNULL(e.lastName,''))) ChangedByName FROM dbo.SRM_PriorityChange p JOIN dbo.SRM_Request r ON r.RequestID=p.RequestID LEFT JOIN dbo.EmployeeInfo e ON e.EmployeeID=p.ApprovedBy WHERE p.PriorityChangeID=@ID;SELECT DISTINCT e.OfficialEmailID FROM dbo.SRM_PriorityChange p JOIN dbo.SRM_Request r ON r.RequestID=p.RequestID LEFT JOIN dbo.EmployeeInfo requestOwner ON requestOwner.EmployeeID=r.RequestedBy LEFT JOIN dbo.SRM_PriorityImpact i ON i.PriorityChangeID=p.PriorityChangeID LEFT JOIN dbo.SRM_Request ir ON ir.RequestID=i.ImpactedRequestID LEFT JOIN dbo.EmployeeInfo impactOwner ON impactOwner.EmployeeID=ir.RequestedBy JOIN dbo.EmployeeInfo e ON e.EmployeeID IN(r.RequestedBy,r.AssignedDeveloperID,requestOwner.ProjectManager,ir.RequestedBy,ir.AssignedDeveloperID,impactOwner.ProjectManager) WHERE p.PriorityChangeID=@ID AND NULLIF(e.OfficialEmailID,'') IS NOT NULL;SELECT ir.RequestNo,ir.Title,i.PreviousETA,i.RevisedETA,i.DelayDays FROM dbo.SRM_PriorityImpact i JOIN dbo.SRM_Request ir ON ir.RequestID=i.ImpactedRequestID WHERE i.PriorityChangeID=@ID;",cn)){Add(c,"@ID",changeId);return Set(c);}}
  public void AddAttachment(long id,int by,string original,string stored,string type,long size){using(var cn=Open())using(var c=new SqlCommand("IF NOT EXISTS(SELECT 1 FROM dbo.SRM_Request WHERE RequestID=@ID AND RequestedBy=@By) THROW 50001,'Access denied.',1;INSERT dbo.SRM_Attachment(RequestID,OriginalFileName,StoredFileName,ContentType,FileSize,UploadedBy) VALUES(@ID,@Original,@Stored,@Type,@Size,@By);",cn)){Add(c,"@ID",id);Add(c,"@By",by);Add(c,"@Original",original);Add(c,"@Stored",stored);Add(c,"@Type",type);Add(c,"@Size",size);c.ExecuteNonQuery();}}
  public DataTable Attachment(long id,int employeeId,bool canViewAll){using(var cn=Open())using(var c=new SqlCommand("SELECT a.* FROM dbo.SRM_Attachment a JOIN dbo.SRM_Request r ON r.RequestID=a.RequestID WHERE a.AttachmentID=@ID AND a.IsActive=1 AND (@All=1 OR r.RequestedBy=@E)",cn)){Add(c,"@ID",id);Add(c,"@E",employeeId);Add(c,"@All",canViewAll);return Table(c);}}
 }
